#!/usr/bin/env python3
"""Fill a HWPX (zip) template with values from training_feedback.json.

Writes /root/training_feedback_ready.hwpx.

Notes:
- HWPX is a ZIP; document body is typically in Contents/section*.xml.
- Placeholder text can be split across multiple hp:t nodes; we merge per paragraph.
- When modifying a paragraph, remove hp:lineSegArray (layout cache) so rendering updates.
"""

from __future__ import annotations

import io
import json
import re
import zipfile
from pathlib import Path
import xml.etree.ElementTree as ET


ROOT = Path("/root")
INPUT_JSON = ROOT / "training_feedback.json"
INPUT_HWPX = ROOT / "training_feedback_template.hwpx"
OUTPUT_HWPX = ROOT / "training_feedback_ready.hwpx"


def _digits_only(value: str) -> str:
    return re.sub(r"[^0-9]", "", value)


def _format_satisfaction(value) -> str:
    # Accept "4.5/5.0", "4.5", 4.5 etc. Preserve the numeric score portion.
    s = str(value).strip()
    m = re.search(r"([0-9]+(?:\.[0-9]+)?)", s)
    score = m.group(1) if m else s
    return f"{score}점 (5.0점 만점)"


def _format_overall_opinion(value: str) -> str:
    base = str(value)
    suffix = "후속 심화반 검토 요망."
    if base.endswith(suffix):
        return base
    if base.endswith(" "):
        return base + suffix
    return base + " " + suffix


def build_replacements(data: dict) -> dict[str, str]:
    rep: dict[str, str] = {}
    for k, v in data.items():
        rep[k] = str(v)

    if "참석자수" in rep:
        rep["참석자수"] = _digits_only(rep["참석자수"])

    if "만족도" in data:
        rep["만족도"] = _format_satisfaction(data["만족도"])

    if "종합의견" in rep:
        rep["종합의견"] = _format_overall_opinion(rep["종합의견"])

    return rep


def replace_placeholders(text: str, replacements: dict[str, str]) -> str:
    out = text
    for k, v in replacements.items():
        out = out.replace("{{" + k + "}}", v)
    return out


def localname(tag: str) -> str:
    # ET uses {uri}local format for namespaced tags.
    if tag.startswith("{") and "}" in tag:
        return tag.split("}", 1)[1]
    return tag


def find_nsmap(root: ET.Element) -> dict[str, str]:
    # Collect namespaces via iterparse.
    # We'll parse again for each file with iterparse to get ns, but for safety.
    return {}


def paragraph_text(p: ET.Element, t_tag: str) -> str:
    parts = []
    for t in p.iter(t_tag):
        parts.append(t.text or "")
    return "".join(parts)


def ensure_single_run_with_text(p: ET.Element, ns_uri: str, new_text: str) -> None:
    run_tag = f"{{{ns_uri}}}run"
    t_tag = f"{{{ns_uri}}}t"

    runs = [e for e in list(p) if e.tag == run_tag]
    if not runs:
        run = ET.Element(run_tag)
        t = ET.SubElement(run, t_tag)
        t.text = new_text
        # Insert at beginning to keep paragraph properties (if any) after
        p.insert(0, run)
        return

    first = runs[0]

    # Remove existing <t> under first run and create one
    for child in list(first):
        if child.tag == t_tag:
            first.remove(child)
    t = ET.SubElement(first, t_tag)
    t.text = new_text

    # Remove all additional runs
    for r in runs[1:]:
        p.remove(r)


def remove_line_seg_array(p: ET.Element, ns_uri: str) -> None:
    # In our sample it's <hp:linesegarray> (lowercase) not lineSegArray.
    # Remove both variants to be safe.
    candidates = {f"{{{ns_uri}}}lineSegArray", f"{{{ns_uri}}}linesegarray"}
    for child in list(p):
        if child.tag in candidates:
            p.remove(child)


def process_section_xml(xml_bytes: bytes) -> tuple[bytes, dict]:
    # Discover namespace mapping
    ns = {}
    for event, elem in ET.iterparse(io.BytesIO(xml_bytes), events=("start-ns",)):
        prefix, uri = elem
        ns[prefix] = uri

    tree = ET.ElementTree(ET.fromstring(xml_bytes))
    root = tree.getroot()

    # Determine hp namespace URI used for paragraphs and text.
    # Usually prefix 'hp'. Fall back to root tag's uri.
    hp_uri = ns.get("hp")
    if not hp_uri and root.tag.startswith("{"):
        hp_uri = root.tag.split("}", 1)[0].lstrip("{")
    if not hp_uri:
        raise RuntimeError("Could not determine hp namespace URI")

    p_tag = f"{{{hp_uri}}}p"
    t_tag = f"{{{hp_uri}}}t"

    modified_paras = 0

    # Iterate paragraphs
    for p in root.iter(p_tag):
        merged = paragraph_text(p, t_tag)
        if "{{" not in merged:
            continue

        replaced = replace_placeholders(merged, REPLACEMENTS)
        if replaced != merged:
            ensure_single_run_with_text(p, hp_uri, replaced)
            remove_line_seg_array(p, hp_uri)
            modified_paras += 1

    # Serialize preserving utf-8 and XML declaration
    out = ET.tostring(root, encoding="utf-8", xml_declaration=True)
    return out, {
        "hp_uri": hp_uri,
        "modified_paragraphs": modified_paras,
        "namespaces": ns,
    }


def iter_content_xml_names(z: zipfile.ZipFile) -> list[str]:
    return [
        n
        for n in z.namelist()
        if n.startswith("Contents/") and n.endswith(".xml")
    ]


def write_hwpx_with_replacements() -> None:
    with INPUT_JSON.open("r", encoding="utf-8") as f:
        data = json.load(f)

    global REPLACEMENTS
    REPLACEMENTS = build_replacements(data)

    with zipfile.ZipFile(INPUT_HWPX, "r") as zin:
        names = zin.namelist()
        content_xmls = iter_content_xml_names(zin)

        modified = {}
        meta = {}
        for name in content_xmls:
            xml_bytes = zin.read(name)
            new_bytes, info = process_section_xml(xml_bytes)
            modified[name] = new_bytes
            meta[name] = info

        # Write new zip
        with zipfile.ZipFile(OUTPUT_HWPX, "w") as zout:
            # If a mimetype file exists, it must be first and uncompressed.
            if "mimetype" in names:
                zout.writestr(
                    "mimetype",
                    zin.read("mimetype"),
                    compress_type=zipfile.ZIP_STORED,
                )

            for name in names:
                if name == "mimetype":
                    continue
                data_bytes = modified.get(name)
                if data_bytes is None:
                    data_bytes = zin.read(name)
                zout.writestr(name, data_bytes, compress_type=zipfile.ZIP_DEFLATED)

    # Light logging
    for name, info in meta.items():
        print(f"{name}: hp_uri={info['hp_uri']} modified_paragraphs={info['modified_paragraphs']}")


if __name__ == "__main__":
    if not INPUT_JSON.exists():
        raise SystemExit(f"Missing {INPUT_JSON}")
    if not INPUT_HWPX.exists():
        raise SystemExit(f"Missing {INPUT_HWPX}")
    write_hwpx_with_replacements()
    print(f"Wrote: {OUTPUT_HWPX}")

